[Query]
public async Task<Book?> GetBookAsync(int id, [Service] AppDbContext db)
{
    var book = await db.Books.FindAsync(id);
    if (book == null)
    {
        throw new GraphQLException(
            "Book not found.");
    }
    return book;
}

public class GlobalExceptionFilter : IExceptionFilter
{
    public async ValueTask OnExceptionAsync(IExceptionContext context)
    {
        if (context.Exception is NotFoundException ex)
        {
            context.Error = new Error("Resource not found.", code: "NOT_FOUND");
            context.Exception = null;
        }
    }
}

// Register
builder.Services
    .AddGraphQLServer()
    .AddExceptionFilter<GlobalExceptionFilter>();
